"""Add original Spring release-boundary lessons with explicit verification limits."""
from __future__ import annotations

import datetime
import html
import json
import pathlib
import re
import uuid

ROOT = pathlib.Path(__file__).resolve().parents[1]
FILE = ROOT / "src/data/fixtures.json"
rows = json.loads(FILE.read_text())
by = {row["path"]: row for row in rows}
stamp = datetime.datetime.now(datetime.UTC).isoformat()


def link_text(value: str) -> str:
    escaped = html.escape(value)
    return re.sub(
        r"\[\[([^|]+)\|([^\]]+)\]\]",
        lambda match: '<a href="/' + match[1] + '">' + match[2] + "</a>",
        escaped,
    )


def paragraph(value: str) -> str:
    return "<p>" + link_text(value) + "</p>"


# These are editorial explanations and bounded design sketches. The earlier kit tests
# remain the source of checked behavior; this pass does not claim deployment tests.
lessons = [
    dict(section="spring-boot", slug="boot-environment-variable-binding", title="Spring Boot environment variables: bind the intended key, not a lookalike", opening="Spring Boot can bind an operating-system environment variable to a canonical configuration property after normalizing its name.", headings=[
        ("Translate the key deliberately", ["For the relay setting relay.batch-size, replace the dot with an underscore, remove the dash, then use uppercase: RELAY_BATCHSIZE. RELAY_BATCH_SIZE looks natural, but it is a different spelling. Put the canonical property and its deployment spelling in the same change review. [[spring/configuration-properties|The typed settings bean]] should reject an unusable number after binding.", "An environment variable usually outranks a packaged application file. It does not outrank every possible source: a command-line argument can still replace it. [[spring/boot-config-source-priority|The earlier H2 collision]] shows why a programmatic default is especially weak. Record the final non-secret value and its source when diagnosing a rollout; do not print credential values." ]),
        ("Test the process that receives it", ["A test that inserts MapPropertySource into an Environment has not proved the operating system passed RELAY_BATCHSIZE to a launched process. A real boundary test must start a child process with that variable, inspect the bound value and stop it. The current source kit does not run that child-process check.", "A typo may leave the packaged default active. If that default admits too many rows per tick, [[spring/poller-batch-limit|the worker budget]] changes without an obvious startup failure. For required deployment keys, validate both presence and range. Keep separate tests for CLI overrides, because the operator may intentionally supersede the environment."] )], code="RELAY_BATCHSIZE=29\n# Canonical property: relay.batch-size\n# Verify the value in a launched child process before release.", lang="bash", proof="No process-environment test exists in the source kit. BootRelaySettingsTest checks file and CLI sources only", limit="The mapping is a documented configuration rule, not a checked deployment environment in this kit. Shells, container manifests and secret injection still need an end-to-end test.", mistakes=["Do not invent an extra underscore for a dash in a canonical key.", "Do not treat a manual property source as a process-environment test.", "Do not log a secret to explain property precedence."], related=["spring/configuration-properties", "spring/boot-config-source-matrix", "spring/boot-config-source-priority", "spring/poller-batch-limit"]),
    dict(section="spring-boot", slug="boot-relative-config-import", title="Spring Boot relative config imports: resolve from the declaring file", opening="A relative config import is resolved from the file that declares it, which can differ from the process working directory.", headings=[
        ("Follow the declaring file", ["Suppose /etc/receipt/application.properties imports optional:relay/worker.properties. The relative path belongs beneath /etc/receipt, not beneath whichever directory the Java process started in. A nested import inside relay/worker.properties uses that nested file as its own base. A file: prefix selects a fixed path instead.", "This matters during packaging. A local test might run from the repository root while a container starts from /app. If the import is optional, both starts can succeed with different values. [[spring/boot-optional-config-import|The missing optional test]] proves only that fallback is allowed, not that the operator file was found." ]),
        ("Choose failure behavior by ownership", ["A required deployment file should fail startup when absent. [[spring/boot-required-config-import|The required-import fixture]] covers that narrow condition. A developer-only override can be optional, but its absence should be visible through a redacted startup diagnostic. Do not make a required credential optional to quiet a bad mount.", "Move the same packaged artifact between two launch directories in a release test. Inspect the bound non-secret value after each start and confirm the expected file was loaded. The kit has a temporary-file test for additional locations; it does not exercise nested relative imports or a container volume."] )], code="spring.config.import=optional:relay/worker.properties\n# In /etc/receipt/application.properties, this resolves under /etc/receipt/relay/.", lang="properties", proof="The source kit tests a missing required import and a missing optional file, not nested relative resolution", limit="No mounted directory, container working-directory change or nested import is exercised by the Maven suite.", mistakes=["Do not resolve every relative import against the shell working directory.", "Do not mistake optional startup for proof that a file loaded.", "Do not put credential contents in a config-origin diagnostic."], related=["spring/boot-required-config-import", "spring/boot-optional-config-import", "spring/boot-additional-config-file", "spring/boot-external-config-validation"]),
    dict(section="spring-production", slug="boot-graceful-shutdown", title="Spring Boot graceful shutdown: finish accepted requests within a deadline", opening="Graceful shutdown gives accepted HTTP requests a bounded chance to finish while the server stops admitting new work.", headings=[
        ("Budget the whole stop sequence", ["A receipt POST may be inside validation, a database transaction or an external call when termination begins. Set a shutdown-phase deadline that is longer than the expected in-flight request but shorter than the platform termination allowance. A 20-second Spring phase inside a 10-second container kill window cannot complete as intended.", "The embedded server's graceful stop is part of application-context close. New requests may be rejected at the network layer, and persistent connections complicate what a client observes. A client that loses the response after a committed write needs [[spring/idempotent-receipt-post|an idempotency contract]] before retrying. Shutdown does not roll back every action already committed." ]),
        ("Prove the signal path", ["Run the packaged application as a child process, hold one bounded request open, send the platform's normal termination signal, and record whether the response finishes. Then try a new request. Repeat with the real ingress or proxy, because a direct loopback test misses connection draining in front of the process.", "The current kit tests live health and authentication over loopback, not a shutdown signal. [[spring/readiness-health-group|The readiness fixture]] shows a dependency outage; it does not prove termination behavior. The configured phase deadline is a policy until the deployed process test runs."] )], code="spring.lifecycle.timeout-per-shutdown-phase=20s\n# Platform termination allowance must exceed this phase and its other stop work.", lang="properties", proof="No graceful-stop process test exists in the source kit. ReadinessHealthGroupHttpTest covers a different live HTTP boundary", limit="The property is a release setting, not evidence that a proxy drains connections or that a committed POST response reaches the client.", mistakes=["Do not set the platform kill deadline shorter than the application stop budget.", "Do not assume a lost response means a database transaction rolled back.", "Do not infer server shutdown behavior from a direct context-close unit test."], related=["spring/readiness-health-group", "spring/idempotent-receipt-post", "spring/receipt-api-project", "spring/poller-shutdown"]),
    dict(section="spring-production", slug="worker-drain-on-shutdown", title="Spring worker shutdown: release admission before a lease expires", opening="A scheduled worker must stop taking new records and account for in-flight claims when the application terminates.", headings=[
        ("Separate new work from owned work", ["The local poller uses a bounded batch and a lease token. On termination, cancel the next poll first. A record already claimed still needs one of two outcomes: finish delivery and acknowledge with its current token, or leave the claim to expire so another worker can retry. A stale worker must never acknowledge after another owner has renewed or replaced the lease.", "[[spring/outbox-fenced-ack|Token-fenced acknowledgement]] and [[spring/outbox-lease-renewal|lease renewal]] are checked against H2. Those tests use direct calls and a logical clock. They do not demonstrate how the deployed scheduler receives a stop signal or how a broker publication is confirmed." ]),
        ("Do not promise exactly once", ["If the consumer commits and the worker dies before acknowledgement, the event returns after lease expiry. [[spring/poller-lost-ack|The lost-ack fixture]] checks this local replay; the consumer's event-ID reservation must make the second delivery safe. A shutdown hook cannot eliminate this interval.", "Choose an in-flight deadline shorter than the lease or renew while work continues. Record backlog age, claims still active at stop and the number of expired leases after restart. The current source kit cancels a test scheduler cleanly, but no scheduler runs inside ReceiptApplication."] )], code="stop accepting new polls\nfinish or abandon each claimed event before the stop deadline\nacknowledge only with the current lease token", lang="text", proof="ScheduledOutboxPollerTest, ConcurrentOutboxLeaseTest and OutboxRelayFlowTest check local states; no deployed stop signal is tested", limit="The source kit uses H2 and a fake transport. Broker confirmation, process death and restart recovery are still untested.", mistakes=["Do not start a new batch after the stop decision.", "Do not acknowledge with an expired lease token.", "Do not claim graceful shutdown removes duplicate-delivery risk."], related=["spring/poller-shutdown", "spring/outbox-fenced-ack", "spring/outbox-lease-renewal", "spring/poller-lost-ack"]),
    dict(section="spring-production", slug="readiness-during-termination", title="Spring readiness during termination: stop routing before stopping dependencies", opening="Readiness controls whether a process should receive new traffic; liveness answers whether restarting it may help.", headings=[
        ("Withdraw traffic in order", ["An instance about to stop should become unavailable to routing before its database pool or worker resources are torn down. Otherwise a load balancer can send a new receipt command into a half-closed application. Spring's availability state and Actuator health groups provide a place to expose that decision, but the platform's probe interval and ingress drain delay determine when traffic actually stops.", "[[spring/readiness-health-group|The existing HTTP test]] forces a test dependency DOWN and sees readiness return 503 while liveness remains 200. That does not test a termination event. External database trouble should not automatically turn liveness into failure; repeated restarts can increase the outage." ]),
        ("Measure the routing lag", ["A release test needs the real platform: withdraw readiness, timestamp the final routed request, then allow in-flight work to finish under [[spring/boot-graceful-shutdown|the stop budget]]. Record errors across old and new instances while the rollout occurs. A loopback GET against one instance cannot show what the ingress did.", "Keep the health response narrow. [[spring/health-probe-security|The security fixture]] exposes nested health paths without opening the API. Internal dependency details should remain protected, while the platform receives only the status it needs to route traffic."] )], code="management.endpoint.health.probes.enabled=true\n# Measure platform probe and routing lag during the actual rollout.", lang="properties", proof="ReadinessHealthGroupHttpTest checks local health groups and API access; no termination-routing test exists", limit="No ingress, platform probe interval, SIGTERM path or multi-instance rollout is measured.", mistakes=["Do not tear down a required dependency before traffic is withdrawn.", "Do not make every external outage a liveness failure.", "Do not expose full health details on a public probe path."], related=["spring/readiness-health-group", "spring/liveness-readiness-separation", "spring/health-probe-security", "spring/boot-graceful-shutdown"]),
    dict(section="spring-web", slug="restclient-request-factory", title="Spring RestClient request factories: pin the transport you test", opening="RestClient is a synchronous HTTP client whose request factory determines the network transport used by each call.", headings=[
        ("The classpath can change the transport", ["A client built without an explicit request factory may select a different implementation when HTTP libraries are added or removed. That can change connection-pool behavior, timeout support and error handling even when the call site stays the same. For a receipt-risk lookup, configure the transport deliberately and run the same library set in tests and the packaged artifact.", "RestClient itself is reusable across threads. That does not make the upstream service fast, nor does it supply a safe retry policy. [[spring/restclient-timeout-budget|The timeout lesson]] treats the transport setting as part of a larger request deadline, and [[spring/restclient-idempotent-retry|the retry lesson]] separates read calls from writes." ]),
        ("Keep response ownership visible", ["A synchronous request occupies a calling thread until it completes or fails. If a servlet handler calls the downstream service, enough simultaneous slow responses can exhaust its request workers. Bound the client call and the number of concurrent admissions; measure saturation with an actual slow local server, then with the real upstream failure mode.", "The current source kit has no RestClient network fixture. The configuration below is a design sketch, not a compiled or load-tested example. Do not extrapolate performance from [[spring/reactive-demand|reactive demand tests]] to this blocking client."] )], code="RestClient riskClient = RestClient.builder()\n    .requestFactory(selectedRequestFactory)\n    .baseUrl(riskServiceBaseUrl)\n    .build();", lang="java", proof="No RestClient request-factory test exists in the source kit; the code is a configuration sketch", limit="The selected factory, connection pool and timeout behavior require a packaged-artifact test with the chosen HTTP library.", mistakes=["Do not assume the same classpath always selects the same transport.", "Do not call a blocking client non-blocking because the server also has WebFlux dependencies.", "Do not treat a reusable client as proof of bounded upstream latency."], related=["spring/restclient-timeout-budget", "spring/restclient-idempotent-retry", "spring/reactive-demand", "spring/async-boundaries"]),
    dict(section="spring-web", slug="restclient-timeout-budget", title="Spring HTTP client timeouts: bound the call inside the request deadline", opening="A downstream timeout is one part of the total deadline for a request that may also wait for a connection, execute SQL and serialize a response.", headings=[
        ("Spend one budget", ["Suppose the public receipt endpoint allows 900ms. Spending 700ms on a risk lookup leaves only 200ms for connection acquisition, local validation, transaction commit and response delivery. Two retries of that 700ms call cannot fit. Write down a maximum elapsed time for the whole request, then allocate connect, response and retry budgets beneath it.", "Different request factories expose different timeout controls. Select the actual factory first; test connect refusal, a server that accepts but never responds, and a slow body. A successful localhost response says nothing about these paths. [[spring/restclient-request-factory|The transport choice]] is part of the contract." ]),
        ("Keep transactions short", ["Do not hold a database transaction open while waiting on a slow third-party request unless the business rule truly requires it and the lock cost is understood. A client timeout after the remote server commits can still leave an uncertain result. [[spring/outbox-atomic-write|The outbox boundary]] records local intent atomically, then performs external delivery separately.", "The current kit checks local H2 transaction behavior and a fake transport retry, not a real HTTP client under latency. The snippet is a budget worksheet; no configured request-factory timeout is claimed as tested here."] )], code="public request deadline: 900ms\nconnection acquisition + connect: 120ms\nupstream response: 450ms\nlocal transaction and response reserve: 330ms", lang="text", proof="No live RestClient timeout test exists; OutboxRelayFlowTest checks a separate fake-transport retry boundary", limit="The budget is illustrative. Production values require measured latency distributions, the chosen transport and real upstream failure tests.", mistakes=["Do not add per-attempt timeouts that exceed the public request deadline.", "Do not keep a database transaction open across an avoidable network wait.", "Do not infer remote non-commit from a client-side timeout."], related=["spring/restclient-request-factory", "spring/restclient-idempotent-retry", "spring/outbox-atomic-write", "spring/transaction-propagation"]),
    dict(section="spring-web", slug="restclient-idempotent-retry", title="Spring HTTP retries: only replay a command with a defined identity", opening="A timeout after sending a remote write leaves its result uncertain, so retry safety depends on the upstream command contract.", headings=[
        ("Differentiate reads from writes", ["A bounded GET may be repeated after a transient connection failure if the read has no side effect and the deadline permits another attempt. A POST that creates a payment or reserves inventory cannot be retried blindly. The remote side may have committed before the response was lost. Attach a stable command identifier only when the upstream accepts and enforces it.", "[[spring/idempotent-receipt-post|The local POST fixture]] stores a response against a key but lives in one process. [[spring/tenant-idempotency-key-scope|The tenant command fixture]] puts replay state in the same H2 transaction as the mutation. Neither proves the behavior of an external risk or payment service." ]),
        ("Treat retry as a state machine", ["Track original request, uncertain result, retry attempt, duplicate response and final reconciliation. Enforce a total deadline and an attempt cap. Retry only the failure classes that the upstream contract permits; a validation error should not enter a backoff loop. If the upstream cannot deduplicate, create a reconciliation path instead of claiming safe replay.", "A consumer that receives an outbox event twice has the same identity problem. [[spring/consumer-idempotency|The event-ID ledger]] commits deduplication with its local mutation. The current source kit does not call a real downstream HTTP service, so this article defines the release contract to test, not a tested client implementation."] )], code="POST /remote-reservations\nIdempotency-Key: receipt-2048-tenant-east\n# Reuse the same key only for the same normalized command.", lang="http", proof="Local receipt and tenant replay fixtures are checked; no external HTTP retry is executed", limit="No remote service, transport-level failure injection or cross-system reconciliation test is present.", mistakes=["Do not generate a new key on every retry of the same command.", "Do not replay an uncertain write against a server without a deduplication contract.", "Do not retry validation failures as transient outages."], related=["spring/idempotent-receipt-post", "spring/tenant-idempotency-key-scope", "spring/consumer-idempotency", "spring/restclient-timeout-budget"]),
    dict(section="spring-testing", slug="release-process-boundary-tests", title="Spring release tests: distinguish context checks from process and platform checks", opening="A Spring context test proves bean behavior inside one process; it cannot by itself prove process signals, ingress routing or external transport.", headings=[
        ("Write the test at the failing layer", ["For a configuration import, a non-web context is enough to check a missing local file. For RELAY_BATCHSIZE supplied by the OS, launch a child process with that environment. For graceful shutdown, terminate the packaged server with the normal signal while a request is active. For routing drain, place the same artifact behind the intended ingress and measure the last admitted request.", "[[spring/testing-boundaries|The general test guide]] separates unit, context and HTTP coverage. The current kit already has local HTTP health tests, config-import tests, staged H2 migration tests and outbox claim tests. These are evidence for their named local boundaries, not a production release rehearsal." ]),
        ("Capture state after failure", ["Do not stop at a response code. Read the receipt row, outbox row, replay key and migration history after each injected cut point. A lost response can follow a successful commit; an interrupted worker can leave a lease that another instance later claims. [[spring/relay-failure-trace|The relay trace]] lists those persisted states.", "The missing matrix still includes a target database, two application versions running together, a real broker, process kill between consumer commit and acknowledgement, and the actual proxy. An integration environment should run the exact packaged artifact and migration SQL. Keep each failure case bounded so a red test identifies the broken boundary."] )], code="1. Start the packaged old and new applications against a disposable target database.\n2. Apply V2, send old and new writes, then stop one instance mid-request.\n3. Inspect rows, outbox state and routed responses before applying V3.", lang="text", proof="The existing Maven suite checks local contexts, H2 states and loopback HTTP; this multi-process matrix has not run", limit="No target database, ingress, broker, process-kill setup or mixed-version deployment is included.", mistakes=["Do not label a context-close test a graceful platform shutdown test.", "Do not assert only HTTP status while ignoring committed rows.", "Do not apply a breaking migration before proving old-version retirement."], related=["spring/testing-boundaries", "spring/boot-graceful-shutdown", "spring/schema-rollout-tests", "spring/relay-failure-trace"]),
    dict(section="spring-projects", slug="receipt-release-boundary-project", title="Spring Boot project: define the receipt service release boundary", opening="A receipt service release boundary joins configuration, database compatibility, HTTP drain and worker replay into one observable sequence.", headings=[
        ("Assemble a disposable rehearsal", ["Start from the last released schema on the intended database engine. Launch the old application version, apply the nullable expansion, then launch the new version. Keep both alive while reading and writing. Backfill from an authoritative tenant source; only after old writers leave should the NOT NULL phase run. [[spring/boot-versioned-receipt-project|The H2 migration project]] checks a sequential subset, not this live overlap.", "Give the new version its actual environment variables and required imported files. Record redacted effective values. Route it behind the intended proxy, withdraw readiness and terminate it while one accepted request runs. [[spring/boot-graceful-shutdown|The stop lesson]] names the response ambiguity that must be handled with a stable request identity." ]),
        ("Count recovery, not just success", ["Allow the relay to claim work, then kill it after the consumer commits but before acknowledgement. A replacement must wait for lease expiry, retry with the same event ID and avoid a second mutation. [[spring/poller-lost-ack|The local fake-transport fixture]] checks the state transition; this project requires a real broker and target database to establish the release behavior.", "The source kit is still a teaching artifact. ReceiptApplication has fixture Basic credentials, in-memory receipts and no runtime Flyway or scheduler. Promote each dependency only after the corresponding integration test exists. Keep the full failure trace and timing measurements with the release candidate."] )], code="schema V1 -> nullable V2 -> old/new overlap -> verified backfill -> old retired -> V3\ntraffic admitted -> readiness withdrawn -> in-flight request resolved -> process stopped\nclaim -> publish -> consumer commit -> lost ack -> lease expiry -> deduplicated replay", lang="text", proof="This is a project plan assembled from local fixtures; no end-to-end release rehearsal has run", limit="Target database, issuer, broker, proxy, deployment platform and mixed-version processes are not supplied by the kit.", mistakes=["Do not present a sequence diagram as an executed rollout.", "Do not contract a column while an old writer still omits it.", "Do not infer durable recovery from a fake transport and one H2 process."], related=["spring/boot-versioned-receipt-project", "spring/receipt-delivery-project", "spring/boot-graceful-shutdown", "spring/release-process-boundary-tests"]),
]

titles = {path: row["title"] for path, row in by.items()}
titles.update({"spring/" + lesson["slug"]: lesson["title"] for lesson in lessons})
for lesson in lessons:
    path = "spring/" + lesson["slug"]
    assert path not in by, path
    assert all(target in titles for target in lesson["related"]), path
    hub = next(row for row in rows if row["type"] == "subject" and row["subject"] == lesson["section"])
    body = paragraph(lesson["opening"])
    for heading, paragraphs in lesson["headings"]:
        body += "<h2>" + html.escape(heading) + "</h2>"
        body += "".join(paragraph(item) for item in paragraphs)
    body += '<h2>Working sketch</h2><pre><code class="language-' + lesson["lang"] + '">' + html.escape(lesson["code"], quote=False) + "</code></pre>"
    body += "<h2>Verification boundary</h2>" + paragraph(lesson["proof"] + ".")
    body += "<h2>Costs and limits</h2>" + paragraph(lesson["limit"])
    body += "<h3>Common Mistakes</h3><ul>" + "".join("<li>" + html.escape(item) + "</li>" for item in lesson["mistakes"]) + "</ul>"
    body += "<h2>Read next</h2>" + paragraph(", ".join("[[" + target + "|" + titles[target] + "]]" for target in lesson["related"]) + ".")
    row = by["spring/if-match-receipt-write"].copy()
    row.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, "https://aitrove.in/" + path)), type="article", path=path, title=lesson["title"], summary=lesson["opening"], body=body, subject=lesson["section"], difficulty="Intermediate", status="published", tags=["spring", "spring-boot", "release"], featured=False, sort_order=1000 + len(rows), published_at=stamp, created_at=stamp, updated_at=stamp)
    row["data"] = {"subject_root": "spring/spring-boot", "section_path": hub["path"], "kind": "tutorial", "content_format": "html", "reading_minutes": max(4, round(len(re.sub(r"<[^>]+>", " ", body).split()) / 150)), "author_path": "authors/aitrove-editorial", "seo_ready": True, "related": [{"path": target, "title": titles[target]} for target in lesson["related"]], "framework_version": "Spring Boot 4.0.8 / Spring Framework 7", "java_version": "21 source-kit baseline", "verification_suite": lesson["proof"], "download_path": "/downloads/aitrove-spring-source-kit.zip"}
    rows.append(row)
    by[path] = row

groups = {
    "spring-boot": ("Environment and import paths", ["spring/boot-environment-variable-binding", "spring/boot-relative-config-import"]),
    "spring-production": ("Stopping a live service", ["spring/boot-graceful-shutdown", "spring/worker-drain-on-shutdown", "spring/readiness-during-termination"]),
    "spring-web": ("Outbound HTTP boundaries", ["spring/restclient-request-factory", "spring/restclient-timeout-budget", "spring/restclient-idempotent-retry"]),
    "spring-testing": ("Release-process checks", ["spring/release-process-boundary-tests"]),
    "spring-projects": ("Receipt release rehearsal", ["spring/receipt-release-boundary-project"]),
}
for section, (title, paths) in groups.items():
    hub = next(row for row in rows if row["type"] == "subject" and row["subject"] == section)
    hub["data"]["modules"].append({"title": title, "summary": "Follow the boundary from local fixtures to a release test.", "lessons": paths})
    hub["updated_at"] = stamp
    if "<h2>Section lessons</h2>" in hub["body"]:
        all_links = "<ul>" + "".join('<li><a href="/' + path + '">' + html.escape(titles[path]) + "</a></li>" for module in hub["data"]["modules"] for path in module["lessons"]) + "</ul>"
        hub["body"] = re.sub(r"(<h2>Section lessons</h2>)[\s\S]*?(<h2>Continue learning</h2>)", lambda match: match[1] + all_links + match[2], hub["body"])

reverse = {
    "spring/boot-config-source-matrix": ["spring/boot-environment-variable-binding", "spring/boot-relative-config-import"],
    "spring/boot-optional-config-import": ["spring/boot-relative-config-import"],
    "spring/readiness-health-group": ["spring/readiness-during-termination"],
    "spring/poller-shutdown": ["spring/worker-drain-on-shutdown"],
    "spring/idempotent-receipt-post": ["spring/restclient-idempotent-retry"],
    "spring/testing-boundaries": ["spring/release-process-boundary-tests"],
    "spring/receipt-api-project": ["spring/receipt-release-boundary-project"],
    "java/versioned-migrations": ["spring/receipt-release-boundary-project"],
}
for path, targets in reverse.items():
    row = by[path]
    marker = "<h2>Release boundary continuation</h2>"
    row["body"] = row["body"].split(marker)[0] + marker + paragraph("Continue with " + ", ".join("[[" + target + "|" + titles[target] + "]]" for target in targets) + ".")
    row["updated_at"] = stamp

quiz_path = "quizzes/spring-release-boundaries"
assert quiz_path not in by
questions = [
    ("Which environment key corresponds to relay.batch-size under Boot's canonical conversion?", ["RELAY_BATCHSIZE", "RELAY_BATCH_SIZE", "RELAY.BATCH-SIZE"], 0, "Dots become underscores, dashes disappear, and the result is uppercased."),
    ("Does a manual MapPropertySource prove a real OS variable reached a launched process?", ["No", "Yes", "Only for Duration"], 0, "A child-process test must set the environment at process creation."),
    ("A relative import in /etc/receipt/application.properties starts with relay/. What is its base?", ["/etc/receipt", "The Java process working directory", "The JDK installation"], 0, "Relative imports use the file that declares them as the base."),
    ("What does an absent optional import prove?", ["Only that startup can use other sources", "That the file was read", "That secrets are present"], 0, "Successful fallback is not evidence of a loaded file."),
    ("A 20-second graceful phase sits inside a 10-second platform kill allowance. What is wrong?", ["The platform can kill the process first", "The request budget grows to 30 seconds", "The database extends the allowance"], 0, "The platform deadline must leave room for application stop work."),
    ("A POST commits but its response is lost during shutdown. Can the caller infer rollback?", ["No", "Yes", "Only when using JDBC"], 0, "A lost response does not reveal commit state; stable retry identity matters."),
    ("A worker is stopping with a claimed event. Which acknowledgement is safe?", ["One using the current lease token after confirmed work", "Any acknowledgement after lease expiry", "One using the previous owner's token"], 0, "A token-fenced acknowledgement belongs only to the current owner."),
    ("Should an external dependency outage automatically fail liveness?", ["Generally no", "Always yes", "Only for a GET request"], 0, "Restarting every instance may worsen a shared external outage; readiness is the traffic gate."),
    ("What can change a RestClient transport without changing a call site?", ["Its runtime classpath and request-factory choice", "A receipt ID alone", "A database schema version"], 0, "An implicit factory can depend on available HTTP libraries."),
    ("Can two 700ms attempts fit inside a 900ms public deadline with local work?", ["No", "Yes", "Only with a longer SQL transaction"], 0, "Per-attempt budgets must fit the end-to-end deadline."),
    ("When is replaying a remote POST after a timeout safe?", ["When the upstream enforces a stable command identity for the same request", "Whenever the client uses TLS", "Whenever the first response was lost"], 0, "The remote write may have committed before the timeout."),
    ("Which test is needed to prove ingress drain during rollout?", ["A deployed process behind the intended ingress", "A non-web context test", "A local SQL migration test"], 0, "Routing behavior belongs to the platform boundary."),
]
